using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ImageWorkspaceOperations
{
    public string shortcut_string(InputEventKey input){var parts=new List<string>();if(input.CtrlPressed)parts.Add("Ctrl");if(input.AltPressed)parts.Add("Alt");if(input.ShiftPressed)parts.Add("Shift");if(input.MetaPressed)parts.Add("Meta");parts.Add(OS.GetKeycodeString(input.Keycode));return string.Join("+",parts);}
    public void register_commands(Control owner)
    {
        var commands=owner.Get("_commands").AsGodotArray();commands.Clear();void Add(string name,string category,Callable action,string shortcut=""){var command=new Settings{["name"]=name,["category"]=category,["run"]=action};if(shortcut.Length>0)command["shortcut"]=shortcut;commands.Add(command);}void Method(string name,string category,string method,string shortcut="")=>Add(name,category,new Callable(owner,method),shortcut);
        Method("Add image from project","Create","_choose_import");foreach(var entry in new[]{("text","Add text layer"),("shape","Add shape layer"),("basic","Add basic / empty layer")})Add(entry.Item2,"Create",Callable.From(()=>add_layer(owner,entry.Item1)));Method("Parent selected layers","Layer","parent_selected","Ctrl+G");Method("Unparent selected layers","Layer","unparent_selected","Ctrl+Shift+G");Method("Duplicate layers","Layer","duplicate_layers","Ctrl+D");Method("Delete layers","Layer","delete_selected","Backspace");Method("Merge selected layers","Layer","merge_selected");Method("Rasterize for painting","Layer","rasterize_selected");Method("Selection to mask","Mask","selection_to_mask");Method("Copy selection to layer","Selection","selection_to_layer");Add("Select subject","Selection",Callable.From(()=>owner.Call("_smart_select","opaque",Colors.Transparent,.12)));Add("Select background","Selection",Callable.From(()=>owner.Call("_smart_select","transparent",Colors.Transparent,.12)));Add("Grow selection","Selection",Callable.From(()=>owner.Call("_modify_selection","grow",2)));Add("Feather selection","Selection",Callable.From(()=>owner.Call("_modify_selection","feather",3)));Add("Clear pixel selection","Selection",Callable.From(()=>_canvas.clear_selection(Canvas(owner))));Method("Canvas size","Image","_canvas_size_dialog");foreach(var entry in new[]{("Transform and align","_transform_panel"),("Effects and styles","_effects_panel"),("Asset shelf","_asset_shelf"),("Variants","_variants_panel"),("Macros","_automation_panel")})Method(entry.Item1,"Workflow",entry.Item2);Method("Save document","File","save","Ctrl+S");Method("Save As","File","save_as","Ctrl+Shift+S");Method("Export flattened image","File","export_image");Method("Quick export presets","File","_export_presets_panel");Method("Copy style","Style","copy_style");Method("Paste style","Style","paste_style");foreach(var entry in new[]{("union","Vector union"),("subtract","Vector subtract"),("intersect","Vector intersect")})Add(entry.Item2,"Vector",Callable.From(()=>owner.Call("_boolean_shapes",entry.Item1)));Add("Fit canvas","View",Callable.From(()=>_canvas.fit(Canvas(owner))),"F");Method("Load canvas shader effect","Effect","_choose_shader_effect");foreach(string mode in new[]{"left","center_x","right","top","center_y","bottom"})Add("Align "+mode.Replace("_"," "),"Transform",Callable.From(()=>align_selected(owner,mode)));var effects=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_workspace.gd").GetScriptConstantMap()["AVAILABLE_EFFECTS"].AsGodotArray();foreach(var value in effects){string kind=value.AsString();Add("Add "+kind.Replace("_"," ")+" effect","Effect",Callable.From(()=>add_effect(owner,kind)));}foreach(var key in owner.Get("tool_buttons").AsGodotDictionary().Keys){string id=key.AsString();Add("Tool: "+id.Replace("_"," ").Capitalize(),"Tool",Callable.From(()=>owner.Call("_set_tool",id)));}
    }
    public void execute_command(Control owner,Settings command)
    {
        string name=command["name"].AsString();owner.Set("_last_command_name",name);var recent=owner.Get("_recent_commands").AsGodotArray();recent.Remove(name);recent.Insert(0,name);if(recent.Count>12)recent.RemoveAt(recent.Count-1);if(owner.Get("_macro_recording").AsBool())owner.Get("_macro_buffer").AsGodotArray().Add(name);owner.Call("_invoke_action",command["run"]);
    }
    public void run_named_command(Control owner,string name){foreach(var value in owner.Get("_commands").AsGodotArray()){var command=value.AsGodotDictionary();if(command["name"].AsString()==name){execute_command(owner,command);return;}}}
    public void repeat_last_command(Control owner){string name=owner.Get("_last_command_name").AsString();if(name.Length==0){owner.Get("status").As<Label>().Text="Run a command first.";return;}run_named_command(owner,name);}
    public void command_palette(Control owner)
    {
        var popup=new PopupPanel();popup.AddThemeStyleboxOverride("panel",box(new Color("14212e"),new Color("4e887b"),12,14));owner.AddChild(popup);var column=new VBoxContainer{CustomMinimumSize=new Vector2(450,380)};popup.AddChild(column);var search=new LineEdit{PlaceholderText="What would you like to do?"};column.AddChild(search);var results=new ItemList{SizeFlagsVertical=Control.SizeFlags.ExpandFill};column.AddChild(results);var matches=new List<Settings>();void Populate(string query){results.Clear();matches.Clear();var ordered=new List<Settings>();foreach(var value in owner.Get("_commands").AsGodotArray())ordered.Add(value.AsGodotDictionary());var recent=owner.Get("_recent_commands").AsGodotArray();int Rank(Settings command){int index=recent.IndexOf(command["name"]);return index<0?100:index;}ordered.Sort((a,b)=>Rank(a).CompareTo(Rank(b)));var custom=owner.Get("_custom_shortcuts").AsGodotDictionary();foreach(var command in ordered){string name=command["name"].AsString(),shortcut=Get(custom,name,Get(command,"shortcut","")).AsString(),searchable=name+" "+Get(command,"category","").AsString()+" "+shortcut;if(query.Length==0||searchable.Contains(query,StringComparison.OrdinalIgnoreCase)){matches.Add(command);results.AddItem(name+"  ·  "+Get(command,"category","Action").AsString()+(shortcut.Length>0?"  ·  "+shortcut:""));}}foreach(var value in Document(owner).Get("layers").AsGodotArray()){var layer=value.As<Resource>();string label=layer.Get("label").AsString(),id=layer.Get("id").AsString();if(query.Length>0&&(label.Contains(query,StringComparison.OrdinalIgnoreCase)||query.StartsWith("layer",StringComparison.OrdinalIgnoreCase))){matches.Add(new Settings{["name"]="Select layer: "+label,["category"]="Layer",["run"]=Callable.From(()=>{var selected=Canvas(owner).Get("selected").AsGodotArray();selected.Clear();selected.Add(id);selection_changed(owner);})});results.AddItem("Select layer  ·  "+label);}}if(results.ItemCount>0)results.Select(0);}void Activate(long index){if(index>=0&&index<matches.Count){var command=matches[(int)index];popup.Hide();execute_command(owner,command);}}search.GuiInput+=input=>{if(input is InputEventKey key&&key.Pressed&&(key.Keycode is Key.Up or Key.Down)&&results.ItemCount>0){var selected=results.GetSelectedItems();int index=selected.Length>0?selected[0]:0;results.Select(Math.Clamp(index+(key.Keycode==Key.Up?-1:1),0,results.ItemCount-1));search.AcceptEvent();}};search.TextChanged+=Populate;search.TextSubmitted+=_=>{var selected=results.GetSelectedItems();Activate(selected.Length>0?selected[0]:0);};results.ItemActivated+=Activate;Populate("");popup.PopupHide+=popup.QueueFree;popup.PopupCentered(new Vector2I(490,430));search.GrabFocus();
    }
    public void unhandled_key_input(Control owner,InputEvent input)
    {
        if(!owner.IsVisibleInTree()||input is not InputEventKey key||!key.Pressed||key.Echo)return;var viewport=owner.GetViewport();var focus=viewport.GuiGetFocusOwner();if(focus!=null&&focus!=owner&&!owner.IsAncestorOf(focus)||focus is LineEdit or TextEdit)return;string shortcut=shortcut_string(key);foreach(var entry in owner.Get("_custom_shortcuts").AsGodotDictionary())if(entry.Value.AsString()==shortcut){run_named_command(owner,entry.Key.AsString());viewport.SetInputAsHandled();return;}var canvas=Canvas(owner);string tool=canvas.Get("tool").AsString();if(!key.CtrlPressed&&!key.AltPressed&&(tool is "brush" or "eraser" or "fill")){int index=(int)key.Keycode-48;var filtered=new List<Settings>();string filter=owner.Get("_preset_filter").AsString();foreach(var value in owner.Get("_paint_presets").AsGodotDictionary()[tool].AsGodotArray()){var preset=value.AsGodotDictionary();if(filter=="all"||Get(preset,"painting_mode","color").AsString()==filter)filtered.Add(preset);}if(index>=0&&index<10&&index<filtered.Count){_canvas.cancel_gesture(canvas);apply_paint_preset(owner,tool,filtered[index]);viewport.SetInputAsHandled();return;}}
        if(key.CtrlPressed){switch(key.Keycode){case Key.S:owner.Call(key.ShiftPressed?"save_as":"save");break;case Key.Z:if(key.ShiftPressed)redo(owner);else undo(owner);break;case Key.Y:redo(owner);break;case Key.D:duplicate_layers(owner);break;case Key.I:owner.Call("_select_pixel_region",true);break;case Key.C:copy_layers(owner);break;case Key.V:paste_layers(owner);break;case Key.G:if(key.ShiftPressed)unparent_selected(owner);else parent_selected(owner);break;case Key.A:if(key.ShiftPressed)_canvas.clear_selection(canvas);else select_all(owner);break;case Key.K:command_palette(owner);break;case Key.R:if(key.ShiftPressed)repeat_last_command(owner);else return;break;case Key.Bracketright:reorder_selected(owner,1);break;case Key.Bracketleft:reorder_selected(owner,-1);break;default:return;}}
        else{switch(key.Keycode){case Key.Delete:case Key.Backspace:if(tool=="pixel_select")owner.Call("_apply_pixel_selection","delete");else delete_selected(owner);break;case Key.Escape:_canvas.cancel_gesture(canvas);break;case Key.Enter:if(canvas.Get("_drag").AsString()=="object_preview")_canvas.commit_object_selection(canvas);else if(tool=="path")_canvas.finish_path(canvas);else _canvas.confirm_stroke(canvas);break;case Key.F:_canvas.fit(canvas);break;case Key.V:owner.Call("_set_tool","move");break;case Key.B:owner.Call("_set_tool","brush");break;case Key.E:owner.Call("_set_tool","eraser");break;case Key.G:owner.Call("_set_tool","fill");break;case Key.L:owner.Call("_set_tool","lasso_crop");break;case Key.C:owner.Call("_set_tool","crop");break;case Key.M:owner.Call("_set_tool","pixel_select");break;case Key.W:owner.Call("_set_tool","warp");break;case Key.Bracketleft:canvas.Set("brush_size",Math.Max(1,canvas.Get("brush_size").AsDouble()-4));refresh_context(owner);break;case Key.Bracketright:canvas.Set("brush_size",Math.Min(500,canvas.Get("brush_size").AsDouble()+4));refresh_context(owner);break;default:return;}}viewport.SetInputAsHandled();
    }
}
